@app.post("/api/nfts/buy")
async def buy_nft(catalog_id: int = Form(...), user: User = Depends(current_user)):
    async with SessionLocal() as db:
        buyer = await db.scalar(select(User).where(User.id == user.id).with_for_update())
        catalog = await db.get(NftCatalog, catalog_id)
        if not buyer or not catalog:
            raise HTTPException(404, "NFT не найден")
        price = int(catalog.price_stars or 0)
        if int(buyer.stars or 0) < price:
            raise HTTPException(400, f"Недостаточно звёзд. Нужно: {price} ⭐")
        buyer.stars = int(buyer.stars or 0) - price
        last_serial = await db.scalar(nft_serial_query(db, catalog.id))
        item = UserNft(nft_id=catalog.id, owner_id=buyer.id, serial=int(last_serial or 0)+1)
        db.add(item)
        db.add(StarTransaction(user_id=buyer.id, amount=-price, title=f"Списание -{price}⭐️", subtitle=f"Покупка NFT · {catalog.name}"))
        await db.commit()
        await db.refresh(item)
        return {"ok": True, "stars": int(buyer.stars or 0), "nft": nft_asset_public(catalog, item, buyer)}

@app.post("/api/nfts/upgrade")
async def upgrade_nft(nft_id: int = Form(...), user: User = Depends(current_user)):
    async with SessionLocal() as db:
        owner = await db.scalar(select(User).where(User.id == user.id).with_for_update())
        item = await db.scalar(select(UserNft).where(UserNft.id == nft_id, UserNft.owner_id == user.id).with_for_update())
        if not owner or not item:
            raise HTTPException(404, "NFT не найден или он вам не принадлежит")
        catalog = await db.get(NftCatalog, item.nft_id)
        if not catalog:
            raise HTTPException(404, "Модель NFT не найдена")
        if item.upgraded:
            raise HTTPException(400, "Этот NFT уже улучшен")
        active_listing = await db.scalar(select(NftMarketListing).where(NftMarketListing.nft_owner_id == item.id, NftMarketListing.status == "active").limit(1))
        if active_listing:
            raise HTTPException(400, "Сначала снимите NFT с продажи")
        if int(owner.stars or 0) < NFT_UPGRADE_PRICE:
            raise HTTPException(400, f"Недостаточно звёзд. Нужно: {NFT_UPGRADE_PRICE} ⭐")
        variant, background, pattern = choose_nft_upgrade(catalog)
        owner.stars = int(owner.stars or 0) - NFT_UPGRADE_PRICE
        item.upgraded = True
        item.model_variant = variant
        item.background_key = background
        item.pattern_key = pattern
        item.upgraded_at = datetime.now(timezone.utc)
        db.add(StarTransaction(user_id=owner.id, amount=-NFT_UPGRADE_PRICE, title=f"Списание -{NFT_UPGRADE_PRICE}⭐️", subtitle=f"Улучшение NFT · {catalog.name}"))
        await db.commit()
        await db.refresh(item)
        return {"ok": True, "stars": int(owner.stars or 0), "nft": nft_asset_public(catalog, item, owner)}

