    if price < 1:
        raise HTTPException(400, "Цена должна быть больше 0")
    async with SessionLocal() as db:
        item = await db.scalar(select(UserNft).where(UserNft.id == nft_id, UserNft.owner_id == user.id).with_for_update())
        if not item:
            raise HTTPException(404, "NFT не найден или он вам не принадлежит")
        if not item.upgraded:
            raise HTTPException(400, "На NFT Market можно выставлять только улучшенные NFT")
        active = await db.scalar(select(NftMarketListing).where(NftMarketListing.nft_owner_id == item.id, NftMarketListing.status == "active").limit(1))
        if active:
            raise HTTPException(400, "NFT уже выставлен на продажу")
        db.add(NftMarketListing(nft_owner_id=item.id, seller_id=user.id, price_stars=price))
        await db.commit()
        return {"ok": True}

