@app.post("/api/nfts/market/buy")
async def nft_market_buy(listing_id: int = Form(...), user: User = Depends(current_user)):
    async with SessionLocal() as db:
        buyer = await db.scalar(select(User).where(User.id == user.id).with_for_update())
        listing = await db.scalar(select(NftMarketListing).where(NftMarketListing.id == listing_id, NftMarketListing.status == "active").with_for_update())
        if not buyer or not listing:
            raise HTTPException(404, "Объявление не найдено")
        if listing.seller_id == buyer.id:
            raise HTTPException(400, "Нельзя купить собственный NFT")
        item = await db.scalar(select(UserNft).where(UserNft.id == listing.nft_owner_id).with_for_update())
        if not item or item.owner_id != listing.seller_id or not item.upgraded:
            raise HTTPException(400, "NFT больше недоступен для покупки")
        catalog = await db.get(NftCatalog, item.nft_id)
        seller = await db.scalar(select(User).where(User.id == listing.seller_id).with_for_update())
        creator = await db.scalar(select(User).where(func.lower(User.username) == "rayf").with_for_update())
        if not catalog or not seller or not creator:
            raise HTTPException(500, "Не удалось завершить сделку")
        price = int(listing.price_stars)
        if int(buyer.stars or 0) < price:
            raise HTTPException(400, f"Недостаточно звёзд. Нужно: {price} ⭐")
        commission = price * 20 // 100
        payout = price - commission
        buyer.stars = int(buyer.stars or 0) - price
        seller.stars = int(seller.stars or 0) + payout
        creator.stars = int(creator.stars or 0) + commission
        item.owner_id = buyer.id
        listing.status = "sold"
        listing.buyer_id = buyer.id
        listing.sold_at = datetime.now(timezone.utc)
        db.add(StarTransaction(user_id=buyer.id, amount=-price, title=f"Списание -{price}⭐️", subtitle=f"Покупка NFT · {catalog.name}"))
        db.add(StarTransaction(user_id=seller.id, amount=payout, title=f"Продажа +{payout}⭐️", subtitle="NFT Market · комиссия 20%"))
        if commission:
            db.add(StarTransaction(user_id=creator.id, amount=commission, title=f"Комиссия +{commission}⭐️", subtitle=f"NFT Market · @{seller.username}"))
        await db.commit()
        return {"ok": True, "stars": int(buyer.stars or 0), "nft": nft_asset_public(catalog, item, buyer)}

@app.post("/api/nfts/transfer")
async def nft_transfer(nft_id: int = Form(...), username: str = Form(...), user: User = Depends(current_user)):
    target_username = username.strip().lstrip("@").lower()
    if not target_username:
        raise HTTPException(400, "Укажите username получателя")
    async with SessionLocal() as db:
        sender = await db.scalar(select(User).where(User.id == user.id).with_for_update())
        target = await db.scalar(select(User).where(func.lower(User.username) == target_username).with_for_update())
        item = await db.scalar(select(UserNft).where(UserNft.id == nft_id, UserNft.owner_id == user.id).with_for_update())
        if not sender or not item:
            raise HTTPException(404, "NFT не найден или он вам не принадлежит")
        if not target or target.is_banned:
            raise HTTPException(404, "Получатель не найден")
        if target.id == sender.id:
            raise HTTPException(400, "Нельзя передать NFT самому себе")
        active = await db.scalar(select(NftMarketListing).where(NftMarketListing.nft_owner_id == item.id, NftMarketListing.status == "active").limit(1))
        if active:
            raise HTTPException(400, "Сначала снимите NFT с продажи")
        if int(sender.stars or 0) < NFT_TRANSFER_PRICE:
            raise HTTPException(400, f"Недостаточно звёзд. Нужно: {NFT_TRANSFER_PRICE} ⭐")
        catalog = await db.get(NftCatalog, item.nft_id)
        sender.stars = int(sender.stars or 0) - NFT_TRANSFER_PRICE
        item.owner_id = target.id
        db.add(StarTransaction(user_id=sender.id, amount=-NFT_TRANSFER_PRICE, title=f"Списание -{NFT_TRANSFER_PRICE}⭐️", subtitle="Передача NFT"))
        if catalog:
            gift_message = Message(sender_id=sender.id, receiver_id=target.id, text=f"__RAYFNFT__|{catalog.name}|{item.serial}|{NFT_TRANSFER_PRICE}|{sender.username}")
            db.add(gift_message)
        await db.commit()
        return {"ok": True, "stars": int(sender.stars or 0)}


@app.post("/api/stories")
async def create_story(file: UploadFile = File(...), user: User = Depends(current_user)):
    content_type = (file.content_type or "").lower()
    if not (content_type.startswith("image/") or content_type.startswith("video/")):
        raise HTTPException(400, "Для сторис можно выбрать только фото или видео")
    data = await file.read()
    if not data:
        raise HTTPException(400, "Файл пустой")
    if len(data) > MAX_FILE_SIZE:
        raise HTTPException(413, "Файл для сторис максимум 8 МБ")
    now = datetime.now(timezone.utc)
    async with SessionLocal() as db:
        # Старые сторис больше не нужны в активной ленте.
        await db.execute(select(Story).where(Story.user_id == user.id, Story.expires_at <= now))
        story = Story(
            user_id=user.id,
            media_data=data,
            media_type=content_type,
            file_name=file.filename or "story",
            created_at=now,
            expires_at=now + timedelta(hours=24),
        )
        db.add(story)
        await db.commit()
        await db.refresh(story)
        return {"ok": True, "id": story.id, "expires_at": story.expires_at.isoformat()}


